begin;
insert into pn_private.sync_schemas values('remote-request-v1',$schema${"$schema":"https://json-schema.org/draft/2020-12/schema","anyOf":[{"oneOf":[{"type":"object","properties":{"action":{"type":"string","const":"read"},"presentationId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"channelEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"}},"required":["action","presentationId","channelEpoch","taskEpoch"],"additionalProperties":false},{"type":"object","properties":{"action":{"type":"string","const":"send"},"presentationId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"channelEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"command":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"instanceId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"sequence":{"type":"integer","exclusiveMinimum":0,"maximum":2147483647},"input":{"oneOf":[{"type":"object","properties":{"kind":{"type":"string","const":"move"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"activate"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"start"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"drop"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"cancel"}},"required":["kind"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"value"},"value":{"type":"string","pattern":"^-?\\d{1,4}(?:[.,]\\d{1,4}|\\/[1-9]\\d{0,3})?$"}},"required":["kind","value"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"scroll"},"direction":{"anyOf":[{"type":"number","const":-1},{"type":"number","const":1}]}},"required":["kind","direction"],"additionalProperties":false}]}},"required":["id","instanceId","taskEpoch","sequence","input"],"additionalProperties":false}},"required":["action","presentationId","channelEpoch","taskEpoch","command"],"additionalProperties":false}]},{"oneOf":[{"type":"object","properties":{"action":{"type":"string","const":"join"},"presentationId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"channelEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"instanceId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"}},"required":["action","presentationId","channelEpoch","taskEpoch","instanceId"],"additionalProperties":false},{"type":"object","properties":{"action":{"type":"string","const":"read"},"presentationId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"channelEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"}},"required":["action","presentationId","channelEpoch","taskEpoch"],"additionalProperties":false},{"type":"object","properties":{"action":{"type":"string","const":"ack"},"presentationId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"channelEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"instanceId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"receipt":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"applied":{"type":"boolean"},"editable":{"type":"boolean"}},"required":["id","applied","editable"],"additionalProperties":false}},"required":["action","presentationId","channelEpoch","taskEpoch","instanceId","receipt"],"additionalProperties":false}]}]}$schema$::jsonb);
insert into pn_private.sync_schemas values('remote-command-v1',$schema${"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"instanceId":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"taskEpoch":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12})$"},"sequence":{"type":"integer","exclusiveMinimum":0,"maximum":2147483647},"input":{"oneOf":[{"type":"object","properties":{"kind":{"type":"string","const":"move"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"activate"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"start"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"drop"},"x":{"type":"number","minimum":0,"maximum":1},"y":{"type":"number","minimum":0,"maximum":1}},"required":["kind","x","y"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"cancel"}},"required":["kind"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"value"},"value":{"type":"string","pattern":"^-?\\d{1,4}(?:[.,]\\d{1,4}|\\/[1-9]\\d{0,3})?$"}},"required":["kind","value"],"additionalProperties":false},{"type":"object","properties":{"kind":{"type":"string","const":"scroll"},"direction":{"anyOf":[{"type":"number","const":-1},{"type":"number","const":1}]}},"required":["kind","direction"],"additionalProperties":false}]}},"required":["id","instanceId","taskEpoch","sequence","input"],"additionalProperties":false}$schema$::jsonb);
create table pn_private.remote_tools(presentation_id uuid primary key references pn_private.presentations(id) on delete cascade,instance_id uuid not null,task_epoch uuid not null,sequence integer not null default 0,command jsonb,receipt jsonb,sent_at timestamptz,move_at timestamptz,expires_at timestamptz not null default now()+interval '4 hours');
alter table pn_private.remote_tools enable row level security;
revoke all on pn_private.remote_tools from public,anon,authenticated;
create function public.remote_topic_allowed(p_topic text) returns boolean language sql stable security definer set search_path='' as $$
select exists(select 1 from pn_private.presentations p where p_topic='pn:input:'||p.id::text||':'||p.channel_epoch::text and not p.revoked and p.expires_at>now() and
 ((auth.uid()=p.board_id and auth.jwt()->>'is_anonymous'='true') or (auth.uid()=p.owner_id and auth.jwt()->>'is_anonymous'='false')));
$$;
revoke all on function public.remote_topic_allowed(text) from public,anon;
grant execute on function public.remote_topic_allowed(text) to authenticated;
create policy pn_receive_remote_tool on realtime.messages for select to authenticated using(extension='broadcast' and public.remote_topic_allowed((select realtime.topic())));
-- Client INSERT stays denied: teacher command and board receipt use these narrow RPC checks.
create function public.remote_tool_action(p_action text,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid=auth.uid();is_board boolean=coalesce(auth.jwt()->>'is_anonymous','')='true';p pn_private.presentations;r pn_private.remote_tools;cmd jsonb;answer jsonb; changed boolean=false;
begin
 if u is null or jsonb_typeof(p_input)<>'object' or octet_length(p_input::text)>2048 or p_input->>'action'<>p_action or p_action not in ('join','read','send','ack') or not p_input ?& array['action','presentationId','channelEpoch','taskEpoch'] then return '{"error":"INVALID_INPUT"}';end if;
 if not pn_private.matches_sync_schema(p_input,(select body from pn_private.sync_schemas where id='remote-request-v1')) then return '{"error":"INVALID_INPUT"}';end if;
 select * into p from pn_private.presentations where id=(p_input->>'presentationId')::uuid and not revoked and expires_at>now() and ((is_board and board_id=u) or (not is_board and owner_id=u)) for update;
 if not found then return '{"error":"FORBIDDEN"}';end if;
 if p.channel_epoch<>(p_input->>'channelEpoch')::uuid or p.public_state->>'taskEpoch'<>p_input->>'taskEpoch' then return '{"error":"CONFLICT"}';end if;
 if p.public_state->>'mode' not in ('opening','station') then return '{"error":"FORBIDDEN"}';end if;
 delete from pn_private.remote_tools where expires_at<now();
 select * into r from pn_private.remote_tools where presentation_id=p.id;
 if p_action='join' then
  if not is_board or not p_input ? 'instanceId' then return '{"error":"FORBIDDEN"}';end if;
  if r.instance_id is distinct from (p_input->>'instanceId')::uuid or r.task_epoch is distinct from (p_input->>'taskEpoch')::uuid then
   insert into pn_private.remote_tools(presentation_id,instance_id,task_epoch,expires_at) values(p.id,(p_input->>'instanceId')::uuid,(p_input->>'taskEpoch')::uuid,p.expires_at)
   on conflict(presentation_id) do update set instance_id=excluded.instance_id,task_epoch=excluded.task_epoch,sequence=0,command=null,receipt=null,sent_at=null,move_at=null returning * into r;
  end if;
 elsif p_action='send' then
  if is_board then return '{"error":"FORBIDDEN"}';end if;
  cmd=p_input->'command';
  if cmd is null or not pn_private.matches_sync_schema(cmd,(select body from pn_private.sync_schemas where id='remote-command-v1')) then return '{"error":"INVALID_INPUT"}';end if;
  if r.instance_id is null or r.instance_id<>(cmd->>'instanceId')::uuid or r.task_epoch<>(cmd->>'taskEpoch')::uuid or r.task_epoch<>(p_input->>'taskEpoch')::uuid then return '{"error":"CONFLICT"}';end if;
  if r.command->>'id'=cmd->>'id' then
   if r.command<>cmd then return '{"error":"CONFLICT"}';end if;
  else
   if (cmd->>'sequence')::int<>r.sequence+1 then return '{"error":"CONFLICT"}';end if;
   if r.command is not null and r.receipt is null and r.command->'input'->>'kind'<>'move' and r.sent_at>now()-interval '3 seconds' then return '{"error":"CONFLICT"}';end if;
   if cmd->'input'->>'kind'='move' and r.move_at>clock_timestamp()-interval '100 milliseconds' then return '{"error":"RATE_LIMITED"}';end if;
   update pn_private.remote_tools set sequence=(cmd->>'sequence')::int,command=cmd,receipt=null,sent_at=clock_timestamp(),move_at=case when cmd->'input'->>'kind'='move' then clock_timestamp() else move_at end where presentation_id=p.id returning * into r;
   changed=true;
  end if;
 elsif p_action='ack' then
  if not is_board then return '{"error":"FORBIDDEN"}';end if;
  if r.instance_id is null or r.instance_id<>(p_input->>'instanceId')::uuid or r.task_epoch<>(p_input->>'taskEpoch')::uuid then return '{"error":"CONFLICT"}';end if;
  answer=p_input->'receipt';
  if answer is null or jsonb_typeof(answer)<>'object' or not answer ?& array['id','applied','editable'] or exists(select 1 from jsonb_object_keys(answer) k where k not in ('id','applied','editable')) or jsonb_typeof(answer->'applied')<>'boolean' or jsonb_typeof(answer->'editable')<>'boolean' then return '{"error":"INVALID_INPUT"}';end if;
  if r.command->>'id' is distinct from answer->>'id' then return '{"error":"CONFLICT"}';end if;
  update pn_private.remote_tools set receipt=answer where presentation_id=p.id returning * into r;changed=true;
 end if;
 -- Expired input is never delivered after reconnect. Only the latest bounded mailbox exists.
 if r.sent_at<clock_timestamp()-interval '3 seconds' then
  update pn_private.remote_tools set command=null,receipt=null where presentation_id=p.id returning * into r;
 end if;
 answer=jsonb_build_object('instanceId',case when r.task_epoch=(p_input->>'taskEpoch')::uuid then r.instance_id end,'sequence',coalesce(r.sequence,0),'command',r.command,'receipt',r.receipt);
 if changed then
  begin perform realtime.send('{}'::jsonb,'remote','pn:input:'||p.id::text||':'||p.channel_epoch::text,true);exception when others then null;end;
 end if;
 return answer;
exception when invalid_text_representation or numeric_value_out_of_range then return '{"error":"INVALID_INPUT"}';
end $$;
revoke all on function public.remote_tool_action(text,jsonb) from public,anon;
grant execute on function public.remote_tool_action(text,jsonb) to authenticated;
commit;
